import React, { useEffect, useState } from "react";
import { useNavigate, useSearchParams } from "react-router-dom";
import "./BuyHouseList.css";

// Safer INR formatter: never returns "—"
function formatCurrencyINR(value) {
  const n = Number(value);
  if (!isFinite(n) || n <= 0) return "₹0.00";
  if (n >= 1e7) return `₹${(n / 1e7).toFixed(2)} Cr`;
  if (n >= 1e5) return `₹${(n / 1e5).toFixed(2)} L`;
  return `₹${n.toLocaleString("en-IN", { maximumFractionDigits: 0 })}`;
}

const num = (v, d = 0) => {
  const n = Number(v);
  return Number.isFinite(n) ? n : d;
};

export default function BuyHouseList() {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const cityFilter = searchParams.get("city");

  const [houses, setHouses] = useState([]);
  const [loading, setLoading] = useState(true);
  const [err, setErr] = useState("");
  const [revealed, setRevealed] = useState({});
  const [predicted, setPredicted] = useState({});
  const [predicting, setPredicting] = useState({});

  // Lightbox state
  const [lightboxSrc, setLightboxSrc] = useState(null);
  const openLightbox = (src) => setLightboxSrc(src);
  const closeLightbox = () => setLightboxSrc(null);

  // Load + filter
  useEffect(() => {
    const load = async () => {
      setLoading(true);
      setErr("");
      try {
        const res = await fetch(`${process.env.REACT_APP_BACKEND_URL}/buy/houses`);
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const data = await res.json();
        const list = Array.isArray(data) ? data : [];

        // Client-side city/location filter
        let filtered = list;
        if (cityFilter && cityFilter.trim()) {
          const raw = cityFilter.trim().toLowerCase();
          const normalize = (t) =>
            String(t || "")
              .toLowerCase()
              .replace(/\s+/g, "")
              .replace(/[-_]/g, "")
              .replace(/[^a-z0-9]/gi, "");

          const needle = normalize(raw);
          filtered = list.filter((h) => {
            const city = String(h.city || "").toLowerCase();
            const loc = String(h.location || "").toLowerCase();
            if (city.includes(raw) || loc.includes(raw)) return true;
            return (
              normalize(h.city).includes(needle) ||
              normalize(h.location).includes(needle)
            );
          });
        }

        setHouses(filtered);
      } catch (e) {
        console.error("Fetch error:", e);
        setErr("Unable to fetch listings. Please try again.");
      } finally {
        setLoading(false);
      }
    };
    load();
  }, [cityFilter]);

  // Close lightbox on Esc
  useEffect(() => {
    const onKey = (e) => { if (e.key === "Escape") closeLightbox(); };
    if (lightboxSrc) window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [lightboxSrc]);

  async function doPredict(h) {
    const payload = {
      Area_sqft: num(h.area_sqft, 900),
      Property_Type: h.property_type || "Independent House",
      Bedrooms: num(h.bedrooms, 2),
      Bathrooms: num(h.bathrooms, 1),
      Year_Built: num(h.year_built, 2008),
      Condition: h.condition || "Average",

      hospitalApplicable: num(h.hospitalDistance) > 0 ? "applicable" : "notApplicable",
      hospitalDistance: num(h.hospitalDistance, 0),
      schoolApplicable: num(h.schoolDistance) > 0 ? "applicable" : "notApplicable",
      schoolDistance: num(h.schoolDistance, 0),
      railwayApplicable: num(h.railwayDistance) > 0 ? "applicable" : "notApplicable",
      railwayDistance: num(h.railwayDistance, 0),
      busApplicable: num(h.busDistance) > 0 ? "applicable" : "notApplicable",
      busDistance: num(h.busDistance, 0),

      latitude: num(h.latitude, 0),
      longitude: num(h.longitude, 0),

      askingPrice: num(h.actualPrice, 0)
    };

    setPredicting((p) => ({ ...p, [h.id]: true }));
    try {
      const res = await fetch(`${process.env.REACT_APP_BACKEND_URL}/predict/house`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload)
      });
      if (!res.ok) throw new Error(`Predict failed (${res.status})`);
      const data = await res.json();
      const priceNum = Number(data.price);
      setPredicted((p) => ({ ...p, [h.id]: Number.isFinite(priceNum) ? priceNum : 0 }));
    } catch (e) {
      console.error("Predict error:", e);
      setPredicted((p) => ({ ...p, [h.id]: 0 }));
      alert("Prediction failed. Please try again.");
    } finally {
      setPredicting((p) => ({ ...p, [h.id]: false }));
    }
  }

  const goDetails = (h) => navigate(`/house/${h.id}`);

  if (loading) return <div className="buy-loading">Loading listings...</div>;
  if (err) return <div className="buy-error">{err}</div>;

  return (
    <div className="buy-root">
      {/* Filter Header */}
      {cityFilter && (
        <div className="filter-header">
          <h2>
            Houses in <span className="city-name">{cityFilter}</span>
          </h2>
          <a href="/buy-house" className="clear-filter">✕ Clear Filter</a>
        </div>
      )}

      {!houses.length ? (
        <div className="buy-empty">
          {cityFilter ? `No houses found in "${cityFilter}". Try a different city.` : "No houses found."}
        </div>
      ) : (
        houses.map((h) => {
          const isRevealed = revealed[h.id];
          const pred = predicted[h.id];

          const actualPriceNum = num(h.actualPrice, 0);
          const areaNum = num(h.area_sqft, 0);
          const bedsNum = num(h.bedrooms, 0);
          const bathsNum = num(h.bathrooms, 0);

          const showDeal =
            typeof pred === "number" &&
            Number.isFinite(actualPriceNum) &&
            actualPriceNum > 0 &&
            pred < actualPriceNum;

          return (
            <div className="buy-card" key={h.id}>
              {/* Left: image */}
              <div className="buy-card-left">
                <div className="buy-thumb">
                  {h.image ? (
                    <button
                      type="button"
                      className="thumb-click"
                      onClick={() => openLightbox(`${process.env.REACT_APP_BACKEND_URL}${h.image}`)}
                      aria-label="View full image"
                    >
                      <img src={`${process.env.REACT_APP_BACKEND_URL}${h.image}`} alt="" />
                    </button>
                  ) : (
                    <div className="no-img">No Image</div>
                  )}
                  <span className="badge">Resale</span>
                </div>
              </div>

              {/* Middle: meta */}
              <div className="buy-card-mid">
                <div className="buy-title">
                  {(h.property_type || "Property")} in {h.city || h.location || ""}
                </div>

                <div className="buy-meta">
                  <div className="price">{formatCurrencyINR(actualPriceNum)}</div>
                  <div className="meta-item">{areaNum.toLocaleString()} sq.ft</div>
                  <div className="meta-item">{bedsNum} Beds</div>
                  <div className="meta-item">{bathsNum} Baths</div>
                </div>

                {pred != null && (
                  <div className={`predict-row ${showDeal ? "deal-ok" : "deal-warn"}`}>
                    <span>Model price: {formatCurrencyINR(pred)}</span>
                    {showDeal ? (
                      <span className="deal good">Good deal</span>
                    ) : (
                      <span className="deal warn">Above model</span>
                    )}
                  </div>
                )}

                {(h.location || h.city) && (
                  <div className="location-row">
                    <span className="pin">📍</span>
                    <span className="loc-text">{h.location || h.city}</span>
                  </div>
                )}
              </div>

              {/* Right: actions */}
              <div className="buy-card-right">
                <div className="btn-row">
                  <button
                    className="btn btn-primary"
                    onClick={() => setRevealed((r) => ({ ...r, [h.id]: !isRevealed }))}
                  >
                    {isRevealed ? h.contact || "NA" : "Contact"}
                  </button>

                  <button
                    className="btn details"
                    onClick={() => goDetails(h)}
                    title="View full details"
                  >
                    Go Details
                  </button>

                  <button
                    className="btn btn-success"
                    disabled={predicting[h.id]}
                    onClick={() => doPredict(h)}
                  >
                    {predicting[h.id] ? "Predicting..." : "Predict"}
                  </button>
                </div>
              </div>
            </div>
          );
        })
      )}

      {/* Lightbox modal */}
      {lightboxSrc && (
        <div className="lb-overlay" onClick={closeLightbox} role="dialog" aria-modal="true">
          <div className="lb-content" onClick={(e) => e.stopPropagation()}>
            <button className="lb-close" onClick={closeLightbox} aria-label="Close">×</button>
            <img src={lightboxSrc} alt="" />
          </div>
        </div>
      )}
    </div>
  );
}
